const serverId = msg.payload.serverId || 'Unknown System';
const stateNames = Array.isArray(msg.payload.stateNames) ? msg.payload.stateNames.join(', ') : 'All States';

msg.topic = `[Uyuni Alert] States Applied on Server ID ${serverId}`;
msg.payload = `Hello Administrator,

Salt states were successfully applied on Uyuni Server ID: ${serverId}.

Applied States: ${stateNames}
Direct Call: ${msg.payload.directCall}
Force Package Refresh: ${msg.payload.forcePackageListRefresh}
Timestamp: ${new Date().toISOString()}

Regards,
Uyuni Automation Subsystem`;

return msg;
